#!/usr/bin/env bash
# Sanestix invoice generator — fix #1: real logo + fix #2: header overlap
# Run from the ROOT of your repo on the VPS.
set -e

mkdir -p public src/lib/invoice-generator src/components/invoice-generator

echo "Writing public/sanestix-logo.png..."
